/* Generated by mk_loss_bench.py: the trainer's loss task before and after, each copied from its tree's
 * source, timed over ROWS rows of VOCAB logits on one thread (the median of ROUNDS rounds, the two alternating)
 * and every adjoint and term compared byte for byte. usage: loss_bench ROWS VOCAB ROUNDS */
#define _POSIX_C_SOURCE 200809L
#include <math.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#define BCIR_DT_ROW_CHUNK 16
static double now(void) { struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts); return ts.tv_sec+ts.tv_nsec*1e-9; }
static int cmpd(const void *a,const void *b) { double x=*(const double*)a,y=*(const double*)b; return x<y?-1:x>y; }
typedef struct loss_job_before {
  size_t n,v; const float *logits; const uint32_t *targets; float *dl; unsigned char *terms;
} loss_job_before;
static void loss_task_before(void *ctx,size_t task) {
  loss_job_before *jb=(loss_job_before *)ctx; size_t i,j,v=jb->v;
  size_t i0=task*BCIR_DT_ROW_CHUNK,i1=i0+BCIR_DT_ROW_CHUNK<jb->n ? i0+BCIR_DT_ROW_CHUNK : jb->n;
  for (i=i0;i<i1;i++) {
    const float *row=jb->logits+i*v; float *d=jb->dl+i*v; float maxv=row[0]; double sum=0.0,term;
    for (j=1;j<v;j++) if (row[j]>maxv) maxv=row[j];
    for (j=0;j<v;j++) sum+=exp((double)row[j]-maxv);
    term=log(sum)+(double)maxv-row[jb->targets[i]];
    for (j=0;j<v;j++) d[j]=(float)((exp((double)row[j]-maxv)/sum-
        (j==jb->targets[i] ? 1.0 : 0.0))/(double)jb->n);
    memcpy(jb->terms+i*sizeof(double),&term,sizeof(double));
  }
}
#define BCIR_DT_LOSS_ONCE 1024  /* the logits a row keeps: 8 KiB of the task's stack */
typedef struct loss_job_after {
  size_t n,v; const float *logits; const uint32_t *targets; float *dl; unsigned char *terms;
} loss_job_after;
static void loss_task_after(void *ctx,size_t task) {
  loss_job_after *jb=(loss_job_after *)ctx; size_t i,j,v=jb->v,kept=v<BCIR_DT_LOSS_ONCE ? v : BCIR_DT_LOSS_ONCE;
  size_t i0=task*BCIR_DT_ROW_CHUNK,i1=i0+BCIR_DT_ROW_CHUNK<jb->n ? i0+BCIR_DT_ROW_CHUNK : jb->n;
  double e[BCIR_DT_LOSS_ONCE];
  for (i=i0;i<i1;i++) {
    const float *row=jb->logits+i*v; float *d=jb->dl+i*v; float maxv=row[0]; double sum=0.0,term;
    size_t t=jb->targets[i];
    for (j=1;j<v;j++) if (row[j]>maxv) maxv=row[j];
    for (j=0;j<kept;j++) { e[j]=exp((double)row[j]-maxv); sum+=e[j]; }
    for (;j<v;j++) sum+=exp((double)row[j]-maxv);
    term=log(sum)+(double)maxv-row[t];
    for (j=0;j<kept;j++) d[j]=(float)((e[j]/sum-(j==t ? 1.0 : 0.0))/(double)jb->n);
    for (;j<v;j++) d[j]=(float)((exp((double)row[j]-maxv)/sum-(j==t ? 1.0 : 0.0))/(double)jb->n);
    memcpy(jb->terms+i*sizeof(double),&term,sizeof(double));
  }
}

int main(int argc,char **argv) {
  size_t n,v,i,t,tasks; int rounds,r,same; uint64_t s=88172645463325252ull;
  float *lg,*d1,*d2; uint32_t *tg; unsigned char *t1,*t2; double *a,*b;
  if (argc!=4) return 2;
  n=strtoul(argv[1],0,10); v=strtoul(argv[2],0,10); rounds=atoi(argv[3]);
  lg=malloc(n*v*4); d1=malloc(n*v*4); d2=malloc(n*v*4); tg=malloc(n*4); t1=malloc(n*8); t2=malloc(n*8);
  a=malloc(rounds*sizeof(double)); b=malloc(rounds*sizeof(double));
  if (!lg || !d1 || !d2 || !tg || !t1 || !t2 || !a || !b) return 3;
  for (i=0;i<n*v;i++) { s^=s<<13; s^=s>>7; s^=s<<17; lg[i]=(float)((double)(s>>11)/9007199254740992.0*16.0-8.0); }
  for (i=0;i<n;i++) tg[i]=(uint32_t)(i*2654435761u%v);
  {
    loss_job_before jb={n,v,lg,tg,d1,t1}; loss_job_after ja={n,v,lg,tg,d2,t2};
    tasks=(n+BCIR_DT_ROW_CHUNK-1)/BCIR_DT_ROW_CHUNK;
    for (r=-1;r<rounds;r++) {
      double x=now(),y,z;
      for (t=0;t<tasks;t++) loss_task_before(&jb,t);
      y=now();
      for (t=0;t<tasks;t++) loss_task_after(&ja,t);
      z=now();
      if (r>=0) { a[r]=y-x; b[r]=z-y; }
    }
  }
  same=!memcmp(d1,d2,n*v*4) && !memcmp(t1,t2,n*8);
  qsort(a,rounds,sizeof(double),cmpd); qsort(b,rounds,sizeof(double),cmpd);
  printf("{\"rows\":%zu,\"vocab\":%zu,\"rounds\":%d,\"before_ms\":%.4f,\"after_ms\":%.4f,\"before_ns_a_logit\":%.3f,"
         "\"after_ns_a_logit\":%.3f,\"after_over_before\":%.4f,\"bytes_equal\":%s}\n",n,v,rounds,a[rounds/2]*1e3,
         b[rounds/2]*1e3,a[rounds/2]*1e9/(n*v),b[rounds/2]*1e9/(n*v),b[rounds/2]/a[rounds/2],same ? "true" : "false");
  return !same;
}
